/**
 * libe data model.
 *
 * Conventions
 * - Primary keys are UUIDs generated by Postgres.
 * - `day` columns are calendar dates (`YYYY-MM-DD` strings, no timezone).
 * - Minutes-of-day (`start_min`, `end_min`) are 0‥1440 relative to `day`.
 * - Points in time are `timestamptz`, surfaced as JS `Date`.
 * - The TS property `order` maps to the column `sort_order` (ORDER is an SQL keyword).
 *   Lower values come first; gaps are allowed.
 */
import { relations, sql } from 'drizzle-orm';
import {
	boolean,
	check,
	date,
	index,
	integer,
	pgEnum,
	pgTable,
	real,
	text,
	timestamp,
	uuid
} from 'drizzle-orm/pg-core';

const createdAt = () => timestamp('created_at', { withTimezone: true }).notNull().defaultNow();

// ─── Enums ──────────────────────────────────────────────────────────────────

export const taskKind = pgEnum('task_kind', ['quest', 'other']);
export const sessionState = pgEnum('session_state', ['running', 'paused', 'completed']);
export const sessionSource = pgEnum('session_source', ['focus', 'manual', 'pomodoro']);

// ─── Quests ─────────────────────────────────────────────────────────────────

export const quests = pgTable('quests', {
	id: uuid('id').primaryKey().defaultRandom(),
	name: text('name').notNull(),
	description: text('description').notNull().default(''),
	/** A single emoji used as the quest icon. */
	icon: text('icon').notNull().default('✨'),
	/** Key of the quest colour family (see `QUEST_COLORS` in `#lib/quest-colors`). */
	color: text('color').notNull().default('amber'),
	/** Target hours per week; null = no budget. */
	weeklyBudgetH: real('weekly_budget_h'),
	/** Set when the quest is archived/finished. Closed quests are hidden from pickers. */
	closedAt: timestamp('closed_at', { withTimezone: true }),
	order: integer('sort_order').notNull().default(0),
	createdAt: createdAt()
});

// ─── Tasks ──────────────────────────────────────────────────────────────────

export const tasks = pgTable(
	'tasks',
	{
		id: uuid('id').primaryKey().defaultRandom(),
		/** Required for `kind = 'quest'`, must be null for `kind = 'other'`. */
		questId: uuid('quest_id').references(() => quests.id, { onDelete: 'cascade' }),
		kind: taskKind('kind').notNull(),
		title: text('title').notNull(),
		description: text('description').notNull().default(''),
		/** Planned/estimated duration in minutes. */
		durationMin: integer('duration_min'),
		/** Planned day. Null = backlog (not scheduled yet). */
		day: date('day', { mode: 'string' }),
		/** iCalendar RRULE string (e.g. `FREQ=WEEKLY;BYDAY=MO,WE`), null = one-off. */
		recurrenceRule: text('recurrence_rule'),
		doneAt: timestamp('done_at', { withTimezone: true }),
		order: integer('sort_order').notNull().default(0),
		createdAt: createdAt()
	},
	(t) => [
		index('tasks_day_idx').on(t.day),
		index('tasks_quest_idx').on(t.questId),
		check(
			'tasks_kind_quest_chk',
			sql`(${t.kind} = 'quest' AND ${t.questId} IS NOT NULL) OR (${t.kind} = 'other' AND ${t.questId} IS NULL)`
		),
		check('tasks_duration_chk', sql`${t.durationMin} IS NULL OR ${t.durationMin} > 0`)
	]
);

// ─── Blocks (planned time on the timeline) ──────────────────────────────────

export const blocks = pgTable(
	'blocks',
	{
		id: uuid('id').primaryKey().defaultRandom(),
		taskId: uuid('task_id')
			.notNull()
			.references(() => tasks.id, { onDelete: 'cascade' }),
		day: date('day', { mode: 'string' }).notNull(),
		startMin: integer('start_min').notNull(),
		endMin: integer('end_min').notNull(),
		createdAt: createdAt()
	},
	(t) => [
		index('blocks_day_idx').on(t.day),
		check(
			'blocks_range_chk',
			sql`${t.startMin} >= 0 AND ${t.endMin} <= 1440 AND ${t.startMin} < ${t.endMin}`
		)
	]
);

// ─── Sessions (logged time) ─────────────────────────────────────────────────

export const sessions = pgTable(
	'sessions',
	{
		id: uuid('id').primaryKey().defaultRandom(),
		taskId: uuid('task_id')
			.notNull()
			.references(() => tasks.id, { onDelete: 'cascade' }),
		state: sessionState('state').notNull().default('running'),
		startedAt: timestamp('started_at', { withTimezone: true }).notNull().defaultNow(),
		/**
		 * Focus/pomodoro: planned length (countdown target), null = open-ended stopwatch.
		 * Manual logs: the logged length.
		 */
		durationMin: integer('duration_min'),
		/** Sum of all finished pauses in milliseconds. */
		pausedMs: integer('paused_ms').notNull().default(0),
		/** Start of the current pause while `state = 'paused'` (needed for a server-side timer). */
		pausedAt: timestamp('paused_at', { withTimezone: true }),
		endedAt: timestamp('ended_at', { withTimezone: true }),
		source: sessionSource('source').notNull().default('focus'),
		createdAt: createdAt()
	},
	(t) => [
		index('sessions_task_idx').on(t.taskId),
		index('sessions_started_idx').on(t.startedAt),
		check('sessions_paused_chk', sql`${t.pausedMs} >= 0`)
	]
);

// ─── Device pairing (Tauri thin client) ─────────────────────────────────────

export const pairingCodes = pgTable('pairing_codes', {
	code: text('code').primaryKey(),
	expiresAt: timestamp('expires_at', { withTimezone: true }).notNull(),
	used: boolean('used').notNull().default(false),
	createdAt: createdAt()
});

export const devices = pgTable('devices', {
	id: uuid('id').primaryKey().defaultRandom(),
	/** SHA-256 of the device token; the plain token only lives in the device keychain. */
	tokenHash: text('token_hash').notNull().unique(),
	name: text('name').notNull(),
	pairedAt: timestamp('paired_at', { withTimezone: true }).notNull().defaultNow(),
	lastSeenAt: timestamp('last_seen_at', { withTimezone: true })
});

// ─── Relations (for `db.query.*`) ───────────────────────────────────────────

export const questsRelations = relations(quests, ({ many }) => ({ tasks: many(tasks) }));

export const tasksRelations = relations(tasks, ({ one, many }) => ({
	quest: one(quests, { fields: [tasks.questId], references: [quests.id] }),
	blocks: many(blocks),
	sessions: many(sessions)
}));

export const blocksRelations = relations(blocks, ({ one }) => ({
	task: one(tasks, { fields: [blocks.taskId], references: [tasks.id] })
}));

export const sessionsRelations = relations(sessions, ({ one }) => ({
	task: one(tasks, { fields: [sessions.taskId], references: [tasks.id] })
}));

// ─── Inferred types ─────────────────────────────────────────────────────────

export type Quest = typeof quests.$inferSelect;
export type NewQuest = typeof quests.$inferInsert;
export type Task = typeof tasks.$inferSelect;
export type NewTask = typeof tasks.$inferInsert;
export type Block = typeof blocks.$inferSelect;
export type NewBlock = typeof blocks.$inferInsert;
export type Session = typeof sessions.$inferSelect;
export type NewSession = typeof sessions.$inferInsert;
export type PairingCode = typeof pairingCodes.$inferSelect;
export type Device = typeof devices.$inferSelect;
